  it('post200: parseM3U skips rtmp leftover, dedupes URL, keeps http+https', () => {
    const stations = parseM3U(`#EXTM3U
#EXTINF:-1 tvg-name="A200",A200
https://example.com/a200.m3u8
#EXTINF:-1 tvg-name="Dup200",Dup200
https://example.com/a200.m3u8
#EXTINF:-1 tvg-name="Rtmp200",Rtmp200
rtmp://example.com/live200
#EXTINF:-1 tvg-name="B200",B200
http://example.com/b200.m3u8
`);
    expect(stations).toHaveLength(2);
    expect(stations.map((s) => s.name)).toEqual(['A200', 'B200']);
  });

  it('post200: parseM3U prefers tvg-name over display comma name + empty leftover attrs', () => {
    const stations = parseM3U(`#EXTINF:-1 tvg-name="Canon200" tvg-logo="" group-title="" tvg-language="" tvg-country="",Display200
https://example.com/c200.m3u8
`);
    expect(stations[0]).toEqual({
      name: 'Canon200',
      url: 'https://example.com/c200.m3u8',
      logo: '',
      group: '',
      language: '',
      country: '',
    });
  });

  it('post200: parseM3U falls back to comma name when tvg-name missing', () => {
    const stations = parseM3U(`#EXTINF:-1 group-title="Jazz",Comma Name 200
https://example.com/comma200.m3u8
`);
    expect(stations[0].name).toBe('Comma Name 200');
    expect(stations[0].group).toBe('Jazz');
  });

  it('post200: parseM3U ignores leftover tvg-id/catchup/radio attrs without inventing fields', () => {
    const stations = parseM3U(`#EXTINF:-1 tvg-id="x.200" radio="true" catchup="default" tvg-chno="12" tvg-name="Known200",Known200
https://example.com/known200.m3u8
`);
    expect(stations).toHaveLength(1);
    expect(stations[0].name).toBe('Known200');
    expect(stations[0]).not.toHaveProperty('tvg-id');
    expect(stations[0]).not.toHaveProperty('radio');
    expect(stations[0]).not.toHaveProperty('catchup');
    expect(JSON.stringify(stations[0])).not.toMatch(/tvg-id|catchup|tvg-chno/);
  });

  it('post200: leftover #EXTGRP comment does not invent group; URL still binds', () => {
    const stations = parseM3U(`#EXTM3U
#EXTINF:-1 tvg-name="Grp200",Grp200
#EXTGRP:Jazz
https://example.com/grp200.m3u8
`);
    expect(stations).toHaveLength(1);
    expect(stations[0].name).toBe('Grp200');
    expect(stations[0].group).toBeUndefined();
  });

  it('post200: leftover rtsp scheme resets current so next http needs a fresh EXTINF', () => {
    const stations = parseM3U(`#EXTM3U
#EXTINF:-1 tvg-name="Cam200",Cam200
rtsp://cam.example/stream200
https://example.com/orphan200.m3u8
#EXTINF:-1 tvg-name="Ok200",Ok200
https://example.com/ok200.m3u8
`);
    expect(stations.map((s) => s.name)).toEqual(['Ok200']);
  });

  it('post200: leftover EXTINF duration 0 still binds attrs', () => {
    const stations = parseM3U(`#EXTINF:0 tvg-name="Zero200" group-title="Ambient",Zero200
https://example.com/zero200.m3u8
`);
    expect(stations[0]).toMatchObject({ name: 'Zero200', group: 'Ambient', url: 'https://example.com/zero200.m3u8' });
  });

  it('post200: parseM3U does not mutate the leftover input string', () => {
    const raw = '#EXTM3U\n#EXTINF:-1 tvg-name="Imm200",Imm200\nhttps://example.com/imm200.m3u8\n';
    const copy = raw.slice();
    parseM3U(raw);
    expect(raw).toBe(copy);
  });

