    expect(read('test/genres.test.ts').includes(['describe(', "'post236 parser HEAVY deepen"].join(''))).toBe(false);
    expect(read('test/mcp.test.ts').includes(['describe(', "'post236 parser HEAVY deepen"].join(''))).toBe(false);
    expect(read('test/helpers.test.ts').includes(['describe(', "'post236 parser HEAVY deepen"].join(''))).toBe(false);
